//! Chained Monte Carlo simulation orchestrator (`L5`, `crates/engine`).
//!
//! Executes deterministic Monte Carlo simulation loops over synthetic tables (generated by an
//! upstream `TransformAnalysisSpec::Simulate`, `TransformAnalysisSpec::RandomSample`, or
//! deterministic bootstrap resampling of a source `DataSheet`), runs any downstream `Transform`,
//! `Stats`, or `Fit` analysis chain on each simulated iteration, applies fit-quality / convergence /
//! ambiguity exclusion filters (`MonteCarloSpec::exclude_flagged_fits` and
//! `FitFlagRules::exclude_flagged_from_summary`), evaluates conjunction `"Hit"` predicates, and
//! emits structured `Hits`, `Not Hits`, and `All` summary and per-iteration result tabs plus
//! hookable summary scalars.
//!
//! # References
//! - Metropolis, N., & Ulam, S. (1949). The Monte Carlo method. *Journal of the American
//!   Statistical Association*, 44(247), 335–341. <https://doi.org/10.1080/01621459.1949.10483310>
//! - Efron, B., & Tibshirani, R. J. (1993). *An Introduction to the Bootstrap*. Monographs on
//!   Statistics and Applied Probability, 57. Chapman & Hall/CRC.
//!   <https://doi.org/10.1201/9780429246593>
//! - Robert, C. P., & Casella, G. (2004). *Monte Carlo Statistical Methods* (2nd ed.). Springer.
//!   <https://doi.org/10.1007/978-1-4757-4145-2>
//! - Blackman, D., & Vigna, S. (2021). Scrambled linear pseudorandom number generators. *ACM
//!   Transactions on Mathematical Software*, 47(4), Article 36, 1–32.
//!   <https://doi.org/10.1145/3460772>
//! - Motulsky, H. J., & Christopoulos, A. (2004). *Fitting Models to Biological Data Using Linear
//!   and Nonlinear Regression: A Practical Guide to Curve Fitting*. Oxford University Press.
//! - Wilson, E. B. (1927). Probable inference, the law of succession, and statistical inference.
//!   *Journal of the American Statistical Association*, 22(158), 209–212.
//!   <https://doi.org/10.1080/01621459.1927.10502953>

use std::collections::{HashMap, HashSet, VecDeque};
use std::sync::atomic::{AtomicBool, Ordering};

use curvebook_doc::{
    AnalysisKind, AnalysisSpec, Cell, ChecklistItem, ChecklistStatus, CiBound, DataSetColumn, DataSheet, ErrorCode, MonteCarloHitOp,
    MonteCarloHitRule, MonteCarloSpec, MultipleVariablesTable, ProjectDocument, ResultCell, ResultScalarEntry, ResultSheet, ResultStatus, ResultTab,
    ResultTabKind, SheetId, TableArchetype, TransformAnalysisSpec, VariableColumn, VariableRole,
};
use curvebook_math::DeterministicRng;
use curvebook_transform::{TransformContext, execute_analysis_transform, quantile_type6_sorted, wilson_score_ci};

use crate::{EngineError, dag};

/// Maximum number of downstream `ResultSheet`s allowed in a single chained Monte Carlo pipeline.
pub const MAX_MC_CHAIN_SHEETS: usize = 16;

/// Maximum total downstream sheet evaluations (`iterations * chain_len`) permitted in one run.
pub const MAX_MC_TOTAL_CHAIN_EVALS: usize = 500_000;

/// Maximum per-iteration rows materialized inside each `*-iterations` diagnostic [`ResultTab`].
pub const MAX_MC_PREVIEW_ROWS: usize = 1_000;

/// Maximum retained iterations materialized into [`ResultSheet::analyzable_data`].
pub const MAX_MC_ANALYZABLE_ROWS: usize = 10_000;

/// Execution error separating cooperative cancellation from domain/validation failures.
#[derive(Debug)]
pub(crate) enum MonteCarloExecError {
    /// Cooperative cancellation was signaled during execution.
    Cancelled(EngineError),
    /// Validation, budget, or solver failure recorded on the result sheet.
    Domain(String),
}

/// Derive a deterministic, decorrelated 64-bit per-iteration seed from `(master_seed, iteration)`
/// using SplitMix64 finalizer mixing (Blackman & Vigna, 2021).
#[must_use]
pub fn derive_iteration_seed(master_seed: u64, iteration: usize) -> u64 {
    let mut z = master_seed.wrapping_add((iteration as u64).wrapping_add(1).wrapping_mul(0x9E37_79B9_7F4A_7C15));
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

#[derive(Clone)]
enum IterationGenerator {
    /// Re-run an upstream `TransformAnalysisSpec::Simulate` with a fresh per-iteration seed.
    UpstreamSimulate { base_source_ds: DataSheet, template_spec: AnalysisSpec },
    /// Re-run an upstream `TransformAnalysisSpec::RandomSample` with a fresh per-iteration seed.
    UpstreamRandomSample { base_source_ds: DataSheet, template_spec: AnalysisSpec },
    /// Nonparametric bootstrap row resampling (Efron & Tibshirani, 1993) over `source_ds`.
    BootstrapDataSheet { template_ds: DataSheet },
}

#[derive(Clone)]
struct ResolvedTrackedScalar {
    label: String,
    target_sheet_id: Option<SheetId>,
    parameter_key: String,
    data_set_index: Option<usize>,
    builtin_fallback: Option<BuiltinSimSummary>,
}

#[derive(Clone, Copy)]
enum BuiltinSimSummary {
    Mean,
    Sd,
    Median,
}

#[derive(Clone)]
struct PreviewRow {
    iteration_1based: usize,
    status: &'static str,
    hit: Option<bool>,
    values: Vec<Option<f64>>,
}

/// Execute a [`MonteCarloSpec`] analysis sheet against `doc` and its resolved `source_ds`,
/// returning a complete [`ResultSheet`] with `All`, `Hits`, and `Not Hits` summary & iteration
/// tabs, hookable scalars, checklist diagnostics, and `analyzable_data`.
///
/// Implements the chained Monte Carlo workflow described by Metropolis & Ulam (1949), Efron &
/// Tibshirani (1993), Robert & Casella (2004), and Motulsky & Christopoulos (2004).
pub(crate) fn execute_monte_carlo_analysis(
    doc: &ProjectDocument,
    existing: &ResultSheet,
    source_ds: &DataSheet,
    cancelled: Option<&AtomicBool>,
) -> Result<ResultSheet, MonteCarloExecError> {
    let AnalysisKind::MonteCarloSimulation(mc) = &existing.analysis.kind else {
        return Err(MonteCarloExecError::Domain(String::from("expected MonteCarloSimulation analysis kind")));
    };

    validate_monte_carlo_spec(doc, existing, mc)?;

    let Some(source_id) = existing.analysis.source_sheet_id.as_ref() else {
        return Err(MonteCarloExecError::Domain(String::from("Monte Carlo analysis is missing required source_sheet_id")));
    };
    let generator = build_iteration_generator(doc, source_id, source_ds)?;
    let (chain_ids, scratch_template) = build_downstream_chain(doc, existing, mc)?;

    let total_evals = mc.iterations.saturating_mul(chain_ids.len().max(1));
    if total_evals > MAX_MC_TOTAL_CHAIN_EVALS {
        return Err(MonteCarloExecError::Domain(format!(
            "Monte Carlo total downstream evaluations ({total_evals}) exceeds safety budget ({MAX_MC_TOTAL_CHAIN_EVALS}); reduce `iterations` or chain depth"
        )));
    }

    let tracked = resolve_tracked_scalars(doc, mc, &chain_ids)?;
    validate_hit_rules(&mc.hit_rules, tracked.len())?;

    let exclude_flagged = mc.exclude_flagged_fits
        || chain_ids.iter().any(|cid| {
            doc.result_sheet(cid).is_some_and(|rs| {
                matches!(
                    &rs.analysis.kind,
                    AnalysisKind::NonlinearRegression(nl)
                        if nl.fit_flag_rules.as_ref().is_some_and(|rules| rules.exclude_flagged_from_summary)
                )
            })
        });

    let n_scalars = tracked.len();
    let mut all_samples: Vec<Vec<f64>> = vec![Vec::with_capacity(mc.iterations.min(4_096)); n_scalars];
    let mut hit_samples: Vec<Vec<f64>> = vec![Vec::with_capacity(mc.iterations.min(4_096)); n_scalars];
    let mut not_hit_samples: Vec<Vec<f64>> = vec![Vec::with_capacity(mc.iterations.min(4_096)); n_scalars];

    let mut preview_all: Vec<PreviewRow> = Vec::with_capacity(mc.iterations.min(MAX_MC_PREVIEW_ROWS));
    let mut preview_hits: Vec<PreviewRow> = Vec::with_capacity(mc.iterations.min(MAX_MC_PREVIEW_ROWS));
    let mut preview_not_hits: Vec<PreviewRow> = Vec::with_capacity(mc.iterations.min(MAX_MC_PREVIEW_ROWS));

    let mut analyzable_rows: Vec<(usize, bool, Vec<f64>)> = Vec::with_capacity(mc.iterations.min(MAX_MC_ANALYZABLE_ROWS));

    let mut completed_iters = 0_usize;
    let mut retained_iters = 0_usize;
    let mut excluded_flagged_iters = 0_usize;
    let mut failed_iters = 0_usize;
    let mut missing_scalar_iters = 0_usize;
    let mut hits_count = 0_usize;
    let mut not_hits_count = 0_usize;

    let mut scratch = scratch_template;

    for iter_idx in 0..mc.iterations {
        check_cancelled(cancelled)?;
        let iter_seed = derive_iteration_seed(mc.seed, iter_idx);
        let sim_ds = match generate_iteration_sheet(doc, &generator, iter_seed) {
            Ok(ds) => ds,
            Err(_) => {
                failed_iters = failed_iters.saturating_add(1);
                if preview_all.len() < MAX_MC_PREVIEW_ROWS {
                    preview_all.push(PreviewRow {
                        iteration_1based: iter_idx + 1,
                        status: "SimulationFailed",
                        hit: None,
                        values: vec![None; n_scalars],
                    });
                }
                continue;
            }
        };

        completed_iters = completed_iters.saturating_add(1);

        let mut iter_failed = false;
        let mut iter_flagged = false;

        if !chain_ids.is_empty() {
            inject_simulated_source(&mut scratch, source_id, sim_ds.clone());
            for cid in &chain_ids {
                check_cancelled(cancelled)?;
                match dag::recompute_result_sheet_by_id(&mut scratch, cid, cancelled) {
                    Ok(_) => {}
                    Err(err) if err.code == ErrorCode::Cancelled => {
                        return Err(MonteCarloExecError::Cancelled(err));
                    }
                    Err(_) => {
                        iter_failed = true;
                        break;
                    }
                }
                let Some(rs) = scratch.result_sheet(cid) else {
                    iter_failed = true;
                    break;
                };
                if matches!(rs.status, ResultStatus::Failed { .. }) {
                    iter_failed = true;
                    break;
                }
                if is_fit_flagged_or_unconverged(rs) {
                    iter_flagged = true;
                }
            }
        }

        if iter_failed {
            failed_iters = failed_iters.saturating_add(1);
            if preview_all.len() < MAX_MC_PREVIEW_ROWS {
                preview_all.push(PreviewRow { iteration_1based: iter_idx + 1, status: "Failed", hit: None, values: vec![None; n_scalars] });
            }
            continue;
        }

        let extracted = extract_tracked_values(&scratch, &sim_ds, &tracked);

        if exclude_flagged && iter_flagged {
            excluded_flagged_iters = excluded_flagged_iters.saturating_add(1);
            if preview_all.len() < MAX_MC_PREVIEW_ROWS {
                preview_all.push(PreviewRow { iteration_1based: iter_idx + 1, status: "Excluded (Flagged)", hit: None, values: extracted });
            }
            continue;
        }

        let mut finite_vals = Vec::with_capacity(n_scalars);
        let mut all_present = true;
        for opt_v in &extracted {
            if let Some(v) = opt_v.filter(|x| x.is_finite()) {
                finite_vals.push(v);
            } else {
                all_present = false;
                break;
            }
        }
        if !all_present {
            missing_scalar_iters = missing_scalar_iters.saturating_add(1);
            if preview_all.len() < MAX_MC_PREVIEW_ROWS {
                preview_all.push(PreviewRow { iteration_1based: iter_idx + 1, status: "MissingScalar", hit: None, values: extracted });
            }
            continue;
        }

        let is_hit = evaluate_hit_rules(&mc.hit_rules, &finite_vals);
        retained_iters = retained_iters.saturating_add(1);
        if is_hit {
            hits_count = hits_count.saturating_add(1);
        } else {
            not_hits_count = not_hits_count.saturating_add(1);
        }

        for (s_idx, &v) in finite_vals.iter().enumerate() {
            if let Some(col) = all_samples.get_mut(s_idx) {
                col.push(v);
            }
            if is_hit {
                if let Some(col) = hit_samples.get_mut(s_idx) {
                    col.push(v);
                }
            } else if let Some(col) = not_hit_samples.get_mut(s_idx) {
                col.push(v);
            }
        }

        let status_label = if iter_flagged { "Retained (Flagged)" } else { "OK" };
        if preview_all.len() < MAX_MC_PREVIEW_ROWS {
            preview_all.push(PreviewRow { iteration_1based: iter_idx + 1, status: status_label, hit: Some(is_hit), values: extracted.clone() });
        }
        if is_hit {
            if preview_hits.len() < MAX_MC_PREVIEW_ROWS {
                preview_hits.push(PreviewRow { iteration_1based: iter_idx + 1, status: status_label, hit: Some(true), values: extracted });
            }
        } else if preview_not_hits.len() < MAX_MC_PREVIEW_ROWS {
            preview_not_hits.push(PreviewRow { iteration_1based: iter_idx + 1, status: status_label, hit: Some(false), values: extracted });
        }

        if analyzable_rows.len() < MAX_MC_ANALYZABLE_ROWS {
            analyzable_rows.push((iter_idx + 1, is_hit, finite_vals));
        }
    }

    build_monte_carlo_result_sheet(
        existing,
        mc,
        &tracked,
        exclude_flagged,
        &MonteCarloCounts {
            requested: mc.iterations,
            completed: completed_iters,
            retained: retained_iters,
            excluded_flagged: excluded_flagged_iters,
            failed: failed_iters,
            missing_scalar: missing_scalar_iters,
            hits: hits_count,
            not_hits: not_hits_count,
        },
        &all_samples,
        &hit_samples,
        &not_hit_samples,
        &preview_all,
        &preview_hits,
        &preview_not_hits,
        &analyzable_rows,
    )
}

struct MonteCarloCounts {
    requested: usize,
    completed: usize,
    retained: usize,
    excluded_flagged: usize,
    failed: usize,
    missing_scalar: usize,
    hits: usize,
    not_hits: usize,
}

fn check_cancelled(cancelled: Option<&AtomicBool>) -> Result<(), MonteCarloExecError> {
    if cancelled.is_some_and(|flag| flag.load(Ordering::Relaxed)) {
        return Err(MonteCarloExecError::Cancelled(EngineError::with_code(ErrorCode::Cancelled, "Monte Carlo simulation cancelled by caller")));
    }
    Ok(())
}

fn validate_monte_carlo_spec(doc: &ProjectDocument, existing: &ResultSheet, mc: &MonteCarloSpec) -> Result<(), MonteCarloExecError> {
    if mc.iterations == 0 || mc.iterations > MonteCarloSpec::MAX_ITERATIONS {
        return Err(MonteCarloExecError::Domain(format!(
            "Monte Carlo `iterations` ({}) must lie in 1..={}",
            mc.iterations,
            MonteCarloSpec::MAX_ITERATIONS
        )));
    }
    if let Some(ref ds_id) = mc.downstream_result_sheet_id {
        if *ds_id == existing.id {
            return Err(MonteCarloExecError::Domain(format!(
                "Monte Carlo sheet `{}` cannot reference itself as `downstream_result_sheet_id`",
                existing.id
            )));
        }
        if doc.result_sheet(ds_id).is_none() {
            return Err(MonteCarloExecError::Domain(format!("downstream result sheet `{ds_id}` not found")));
        }
    }
    for (idx, ts) in mc.tracked_scalars.iter().enumerate() {
        if ts.label.trim().is_empty() {
            return Err(MonteCarloExecError::Domain(format!("`tracked_scalars[{idx}].label` must not be empty")));
        }
        if ts.parameter_key.trim().is_empty() {
            return Err(MonteCarloExecError::Domain(format!("`tracked_scalars[{idx}].parameter_key` must not be empty")));
        }
        if let Some(ref target_id) = ts.result_sheet_id {
            if *target_id == existing.id {
                return Err(MonteCarloExecError::Domain(format!("Monte Carlo sheet `{}` cannot track a scalar from itself", existing.id)));
            }
            if doc.result_sheet(target_id).is_none() {
                return Err(MonteCarloExecError::Domain(format!("tracked scalar result sheet `{target_id}` not found")));
            }
        } else if mc.downstream_result_sheet_id.is_none() {
            return Err(MonteCarloExecError::Domain(format!(
                "`tracked_scalars[{idx}]` (`{}`) requires `downstream_result_sheet_id` or an explicit `result_sheet_id`",
                ts.label
            )));
        }
    }
    Ok(())
}

fn validate_hit_rules(rules: &[MonteCarloHitRule], scalar_count: usize) -> Result<(), MonteCarloExecError> {
    for (idx, rule) in rules.iter().enumerate() {
        if rule.scalar_index >= scalar_count {
            return Err(MonteCarloExecError::Domain(format!(
                "`hit_rules[{idx}].scalar_index` ({}) is out of range for {scalar_count} tracked scalar(s)",
                rule.scalar_index
            )));
        }
        if !rule.threshold.is_finite() {
            return Err(MonteCarloExecError::Domain(format!("`hit_rules[{idx}].threshold` must be finite")));
        }
        if rule.op == MonteCarloHitOp::Between {
            let Some(hi) = rule.upper_threshold else {
                return Err(MonteCarloExecError::Domain(format!("`hit_rules[{idx}]` with operator `Between` requires finite `upper_threshold`")));
            };
            if !hi.is_finite() || hi < rule.threshold {
                return Err(MonteCarloExecError::Domain(format!(
                    "`hit_rules[{idx}].upper_threshold` ({hi}) must be finite and >= `threshold` ({})",
                    rule.threshold
                )));
            }
        }
    }
    Ok(())
}

fn build_iteration_generator(
    doc: &ProjectDocument,
    source_id: &SheetId,
    resolved_source_ds: &DataSheet,
) -> Result<IterationGenerator, MonteCarloExecError> {
    if let Some(src_rs) = doc.result_sheet(source_id) {
        match &src_rs.analysis.kind {
            AnalysisKind::Transform(TransformAnalysisSpec::Simulate { .. }) => {
                let Some(base_id) = src_rs.analysis.source_sheet_id.as_ref() else {
                    return Err(MonteCarloExecError::Domain(String::from("upstream Simulate analysis is missing source_sheet_id")));
                };
                let base_source_ds = resolve_sheet_table_for_mc(doc, base_id)?;
                return Ok(IterationGenerator::UpstreamSimulate { base_source_ds, template_spec: src_rs.analysis.clone() });
            }
            AnalysisKind::Transform(TransformAnalysisSpec::RandomSample { .. }) => {
                let Some(base_id) = src_rs.analysis.source_sheet_id.as_ref() else {
                    return Err(MonteCarloExecError::Domain(String::from("upstream RandomSample analysis is missing source_sheet_id")));
                };
                let base_source_ds = resolve_sheet_table_for_mc(doc, base_id)?;
                return Ok(IterationGenerator::UpstreamRandomSample { base_source_ds, template_spec: src_rs.analysis.clone() });
            }
            _ => {}
        }
    }
    Ok(IterationGenerator::BootstrapDataSheet { template_ds: resolved_source_ds.clone() })
}

fn resolve_sheet_table_for_mc(doc: &ProjectDocument, id: &SheetId) -> Result<DataSheet, MonteCarloExecError> {
    if let Some(ds) = doc.data_sheet(id) {
        return Ok(ds.clone());
    }
    if let Some(rs) = doc.result_sheet(id)
        && let Some(ref ad) = rs.analyzable_data
    {
        return Ok(ad.clone());
    }
    Err(MonteCarloExecError::Domain(format!("upstream source table `{id}` not found or has no analyzable data")))
}

fn generate_iteration_sheet(doc: &ProjectDocument, generator: &IterationGenerator, iter_seed: u64) -> Result<DataSheet, String> {
    match generator {
        IterationGenerator::UpstreamSimulate { base_source_ds, template_spec } => {
            let mut spec = template_spec.clone();
            if let AnalysisKind::Transform(TransformAnalysisSpec::Simulate { ref mut seed, .. }) = spec.kind {
                *seed = iter_seed;
            }
            let info_opt = base_source_ds.info_sheet_id.as_ref().and_then(|id| doc.info_sheet(id));
            let ctx = TransformContext {
                info_sheet: info_opt,
                info_sheets: &doc.info_sheets,
                result_sheets: &doc.result_sheets,
                data_sheets: &doc.data_sheets,
                selected_data_sets: spec.selected_data_sets.clone(),
                output_id: Some(spec.id.as_str().to_owned()),
                output_title: Some(spec.effective_title().to_owned()),
            };
            let res = execute_analysis_transform(base_source_ds, &spec, &ctx).map_err(|e| e.to_string())?;
            res.analyzable_data.ok_or_else(|| String::from("simulation transform emitted no analyzable_data"))
        }
        IterationGenerator::UpstreamRandomSample { base_source_ds, template_spec } => {
            let mut spec = template_spec.clone();
            if let AnalysisKind::Transform(TransformAnalysisSpec::RandomSample { ref mut seed, .. }) = spec.kind {
                *seed = iter_seed;
            }
            let info_opt = base_source_ds.info_sheet_id.as_ref().and_then(|id| doc.info_sheet(id));
            let ctx = TransformContext {
                info_sheet: info_opt,
                info_sheets: &doc.info_sheets,
                result_sheets: &doc.result_sheets,
                data_sheets: &doc.data_sheets,
                selected_data_sets: spec.selected_data_sets.clone(),
                output_id: Some(spec.id.as_str().to_owned()),
                output_title: Some(spec.effective_title().to_owned()),
            };
            let res = execute_analysis_transform(base_source_ds, &spec, &ctx).map_err(|e| e.to_string())?;
            res.analyzable_data.ok_or_else(|| String::from("random_sample transform emitted no analyzable_data"))
        }
        IterationGenerator::BootstrapDataSheet { template_ds } => bootstrap_resample_datasheet(template_ds, iter_seed),
    }
}

fn bootstrap_resample_datasheet(template: &DataSheet, seed: u64) -> Result<DataSheet, String> {
    let mut rng = DeterministicRng::from_seed(seed);
    let mut out = template.clone();
    match &mut out.archetype {
        TableArchetype::Xy(xy) => resample_xy_table(&mut rng, xy)?,
        TableArchetype::Column(col) => resample_column_table(&mut rng, col),
        TableArchetype::Grouped(grp) => resample_row_columns(&mut rng, &mut grp.row_titles, &mut grp.data_sets),
        TableArchetype::PartsOfWhole(pow) => resample_row_columns(&mut rng, &mut pow.slice_labels, &mut pow.data_sets),
        TableArchetype::Contingency(cont) => resample_contingency_table(&mut rng, cont),
        TableArchetype::Survival(surv) => resample_survival_table(&mut rng, surv)?,
        TableArchetype::MultipleVariables(mv) => resample_mv_table(&mut rng, mv)?,
        TableArchetype::Nested(nt) => resample_nested_table(&mut rng, nt),
    }
    Ok(out)
}

fn resample_xy_table(rng: &mut DeterministicRng, xy: &mut curvebook_doc::XyTable) -> Result<(), String> {
    let n = xy.row_count();
    if n == 0 {
        return Err(String::from("cannot bootstrap empty XY table"));
    }
    let orig_x = xy.x_cells.clone();
    let orig_titles = xy.row_titles.clone();
    let orig_sets: Vec<Vec<Vec<Cell>>> = xy.data_sets.iter().map(|c| c.cells.clone()).collect();
    let picks = sample_bootstrap_indices(rng, n);
    for (dst_r, &src_r) in picks.iter().enumerate() {
        if let (Some(dst), Some(src)) = (xy.x_cells.get_mut(dst_r), orig_x.get(src_r)) {
            *dst = src.clone();
        }
        if let (Some(dst), Some(src)) = (xy.row_titles.get_mut(dst_r), orig_titles.get(src_r)) {
            *dst = src.clone();
        }
        for (c_idx, ds_col) in xy.data_sets.iter_mut().enumerate() {
            if let (Some(dst), Some(src)) = (ds_col.cells.get_mut(dst_r), orig_sets.get(c_idx).and_then(|rows| rows.get(src_r))) {
                *dst = src.clone();
            }
        }
    }
    Ok(())
}

fn resample_column_table(rng: &mut DeterministicRng, col: &mut curvebook_doc::ColumnTable) {
    for ds_col in &mut col.data_sets {
        let active_vals: Vec<Cell> = ds_col.cells.iter().filter_map(|r| r.first()).filter(|c| !c.excluded && !c.is_empty()).cloned().collect();
        if active_vals.is_empty() {
            continue;
        }
        let picks = sample_bootstrap_indices(rng, active_vals.len());
        let mut active_slot = 0_usize;
        for row in &mut ds_col.cells {
            if let Some(cell) = row.first_mut()
                && !cell.excluded
                && !cell.is_empty()
            {
                if let Some(&src_i) = picks.get(active_slot)
                    && let Some(sampled) = active_vals.get(src_i)
                {
                    *cell = sampled.clone();
                }
                active_slot = active_slot.saturating_add(1);
            }
        }
    }
}

fn resample_contingency_table(rng: &mut DeterministicRng, cont: &mut curvebook_doc::ContingencyTable) {
    // Multinomial count resampling preserving total count N across all non-negative cells.
    let mut coords: Vec<(usize, usize)> = Vec::new();
    let mut weights: Vec<f64> = Vec::new();
    let mut total_n = 0_u64;
    for (c_idx, col) in cont.data_sets.iter().enumerate() {
        for (r_idx, row) in col.cells.iter().enumerate() {
            if let Some(v) = row.first().and_then(Cell::active_number)
                && v >= 0.0
            {
                coords.push((c_idx, r_idx));
                weights.push(v);
                #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                {
                    total_n = total_n.saturating_add(v.round() as u64);
                }
            }
        }
    }
    let sum_w: f64 = weights.iter().sum();
    if sum_w <= 0.0 || total_n == 0 || coords.is_empty() {
        return;
    }
    let mut cdf = Vec::with_capacity(weights.len());
    let mut acc = 0.0_f64;
    for w in &weights {
        acc += w / sum_w;
        cdf.push(acc);
    }
    if let Some(last) = cdf.last_mut() {
        *last = 1.0;
    }
    let mut counts = vec![0_u64; coords.len()];
    let draws = total_n.min(1_000_000);
    for _ in 0..draws {
        let u = rng.next_f64();
        let pos = cdf.partition_point(|&p| p < u).min(coords.len().saturating_sub(1));
        if let Some(slot) = counts.get_mut(pos) {
            *slot = slot.saturating_add(1);
        }
    }
    for (&(c_idx, r_idx), &cnt) in coords.iter().zip(&counts) {
        if let Some(cell) = cont.data_sets.get_mut(c_idx).and_then(|c| c.cells.get_mut(r_idx)).and_then(|r| r.first_mut()) {
            #[allow(clippy::cast_precision_loss)]
            {
                *cell = Cell::number(cnt as f64);
            }
        }
    }
}

fn resample_survival_table(rng: &mut DeterministicRng, surv: &mut curvebook_doc::SurvivalTable) -> Result<(), String> {
    let n = surv.times.len();
    if n == 0 {
        return Err(String::from("cannot bootstrap empty Survival table"));
    }
    let orig_times = surv.times.clone();
    let orig_cohorts: Vec<Vec<Vec<Cell>>> = surv.cohorts.iter().map(|c| c.cells.clone()).collect();
    let picks = sample_bootstrap_indices(rng, n);
    for (dst_r, &src_r) in picks.iter().enumerate() {
        if let (Some(dst), Some(src)) = (surv.times.get_mut(dst_r), orig_times.get(src_r)) {
            *dst = src.clone();
        }
        for (c_idx, cohort) in surv.cohorts.iter_mut().enumerate() {
            if let (Some(dst), Some(src)) = (cohort.cells.get_mut(dst_r), orig_cohorts.get(c_idx).and_then(|rows| rows.get(src_r))) {
                *dst = src.clone();
            }
        }
    }
    Ok(())
}

fn resample_mv_table(rng: &mut DeterministicRng, mv: &mut MultipleVariablesTable) -> Result<(), String> {
    let n = mv.row_count();
    if n == 0 {
        return Err(String::from("cannot bootstrap empty MultipleVariables table"));
    }
    let orig_titles = mv.row_titles.clone();
    let orig_vars: Vec<Vec<Cell>> = mv.variables.iter().map(|v| v.cells.clone()).collect();
    let picks = sample_bootstrap_indices(rng, n);
    for (dst_r, &src_r) in picks.iter().enumerate() {
        if let (Some(dst), Some(src)) = (mv.row_titles.get_mut(dst_r), orig_titles.get(src_r)) {
            *dst = src.clone();
        }
        for (v_idx, var) in mv.variables.iter_mut().enumerate() {
            if let (Some(dst), Some(src)) = (var.cells.get_mut(dst_r), orig_vars.get(v_idx).and_then(|rows| rows.get(src_r))) {
                *dst = src.clone();
            }
        }
    }
    Ok(())
}

fn resample_nested_table(rng: &mut DeterministicRng, nt: &mut curvebook_doc::NestedTable) {
    for grp in &mut nt.groups {
        let n = grp.cells.len();
        if n == 0 {
            continue;
        }
        let orig = grp.cells.clone();
        let picks = sample_bootstrap_indices(rng, n);
        for (dst_r, &src_r) in picks.iter().enumerate() {
            if let (Some(dst), Some(src)) = (grp.cells.get_mut(dst_r), orig.get(src_r)) {
                *dst = src.clone();
            }
        }
    }
}

fn resample_row_columns(rng: &mut DeterministicRng, row_titles: &mut [String], cols: &mut [DataSetColumn]) {
    let n = cols.first().map_or(0, |c| c.cells.len());
    if n == 0 {
        return;
    }
    let orig_titles = row_titles.to_vec();
    let orig_cols: Vec<Vec<Vec<Cell>>> = cols.iter().map(|c| c.cells.clone()).collect();
    let picks = sample_bootstrap_indices(rng, n);
    for (dst_r, &src_r) in picks.iter().enumerate() {
        if let (Some(dst), Some(src)) = (row_titles.get_mut(dst_r), orig_titles.get(src_r)) {
            *dst = src.clone();
        }
        for (c_idx, col) in cols.iter_mut().enumerate() {
            if let (Some(dst), Some(src)) = (col.cells.get_mut(dst_r), orig_cols.get(c_idx).and_then(|rows| rows.get(src_r))) {
                *dst = src.clone();
            }
        }
    }
}

fn sample_bootstrap_indices(rng: &mut DeterministicRng, n: usize) -> Vec<usize> {
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        #[allow(clippy::cast_possible_truncation)]
        let idx = (rng.next_u64() % (n as u64)) as usize;
        out.push(idx);
    }
    out
}

fn build_downstream_chain(
    doc: &ProjectDocument,
    existing: &ResultSheet,
    mc: &MonteCarloSpec,
) -> Result<(Vec<SheetId>, ProjectDocument), MonteCarloExecError> {
    let mut targets: Vec<SheetId> = Vec::new();
    if let Some(ref ds_id) = mc.downstream_result_sheet_id {
        targets.push(ds_id.clone());
    }
    for ts in &mc.tracked_scalars {
        if let Some(ref tid) = ts.result_sheet_id
            && !targets.contains(tid)
        {
            targets.push(tid.clone());
        }
    }

    if targets.is_empty() {
        let scratch = ProjectDocument::new("mc-scratch").map_err(|e| MonteCarloExecError::Domain(e.to_string()))?;
        return Ok((Vec::new(), scratch));
    }

    let Some(source_id) = existing.analysis.source_sheet_id.as_ref() else {
        return Err(MonteCarloExecError::Domain(String::from("Monte Carlo analysis is missing required source_sheet_id")));
    };
    let chain_set = collect_source_dependent_chain(doc, source_id, &targets)?;
    let ordered = topo_sort_chain(doc, &chain_set)?;
    let scratch = assemble_scratch_doc(doc, source_id, &chain_set, &ordered)?;
    Ok((ordered, scratch))
}

fn collect_source_dependent_chain(doc: &ProjectDocument, source_id: &SheetId, targets: &[SheetId]) -> Result<HashSet<SheetId>, MonteCarloExecError> {
    let mut ancestors: HashSet<SheetId> = HashSet::new();
    let mut queue: VecDeque<SheetId> = targets.iter().cloned().collect();
    while let Some(cur) = queue.pop_front() {
        if cur == *source_id || !ancestors.insert(cur.clone()) {
            continue;
        }
        if let Some(rs) = doc.result_sheet(&cur) {
            if let Some(src) = rs.analysis.source_sheet_id.as_ref()
                && src != source_id
                && doc.result_sheet(src).is_some()
            {
                queue.push_back(src.clone());
            }
            for up in rs.analysis.kind.upstream_sheet_ids() {
                if up != *source_id && doc.result_sheet(&up).is_some() && !ancestors.contains(&up) {
                    queue.push_back(up);
                }
            }
        }
    }

    let mut depends_on_source: HashSet<SheetId> = HashSet::new();
    depends_on_source.insert(source_id.clone());
    let mut changed = true;
    while changed {
        changed = false;
        for cand in &ancestors {
            if depends_on_source.contains(cand) {
                continue;
            }
            if let Some(rs) = doc.result_sheet(cand)
                && (rs.analysis.source_sheet_id.as_ref().is_some_and(|src| depends_on_source.contains(src))
                    || rs.analysis.kind.upstream_sheet_ids().iter().any(|u| depends_on_source.contains(u)))
            {
                depends_on_source.insert(cand.clone());
                changed = true;
            }
        }
    }

    let chain_set: HashSet<SheetId> = ancestors.iter().filter(|id| depends_on_source.contains(*id)).cloned().collect();
    for target in targets {
        if !chain_set.contains(target) {
            return Err(MonteCarloExecError::Domain(format!(
                "downstream result sheet `{target}` does not depend on Monte Carlo source sheet `{source_id}`"
            )));
        }
    }
    if chain_set.is_empty() {
        return Err(MonteCarloExecError::Domain(format!("downstream result sheet(s) do not depend on Monte Carlo source sheet `{source_id}`")));
    }
    if chain_set.len() > MAX_MC_CHAIN_SHEETS {
        return Err(MonteCarloExecError::Domain(format!(
            "downstream Monte Carlo chain contains {} sheets, exceeding limit ({MAX_MC_CHAIN_SHEETS})",
            chain_set.len()
        )));
    }
    for cid in &chain_set {
        if let Some(rs) = doc.result_sheet(cid)
            && matches!(rs.analysis.kind, AnalysisKind::MonteCarloSimulation(_))
        {
            return Err(MonteCarloExecError::Domain(format!(
                "nested Monte Carlo simulation `{cid}` inside another Monte Carlo chain is not allowed"
            )));
        }
    }
    Ok(chain_set)
}

fn topo_sort_chain(doc: &ProjectDocument, chain_set: &HashSet<SheetId>) -> Result<Vec<SheetId>, MonteCarloExecError> {
    let mut in_deg: HashMap<SheetId, usize> = HashMap::with_capacity(chain_set.len());
    let mut adj: HashMap<SheetId, Vec<SheetId>> = HashMap::with_capacity(chain_set.len());
    for cid in chain_set {
        in_deg.insert(cid.clone(), 0);
    }
    for cid in chain_set {
        if let Some(rs) = doc.result_sheet(cid) {
            let mut deps: HashSet<SheetId> = HashSet::new();
            if let Some(src) = rs.analysis.source_sheet_id.as_ref()
                && chain_set.contains(src)
            {
                deps.insert(src.clone());
            }
            for up in rs.analysis.kind.upstream_sheet_ids() {
                if chain_set.contains(&up) {
                    deps.insert(up);
                }
            }
            for dep in deps {
                adj.entry(dep).or_default().push(cid.clone());
                if let Some(deg) = in_deg.get_mut(cid) {
                    *deg = deg.saturating_add(1);
                }
            }
        }
    }

    let mut ready: Vec<SheetId> = in_deg.iter().filter(|&(_, &d)| d == 0).map(|(id, _)| id.clone()).collect();
    ready.sort();
    let mut ordered = Vec::with_capacity(chain_set.len());
    while let Some(next) = ready.first().cloned() {
        ready.remove(0);
        ordered.push(next.clone());
        if let Some(children) = adj.get(&next) {
            for ch in children {
                if let Some(deg) = in_deg.get_mut(ch) {
                    *deg = deg.saturating_sub(1);
                    if *deg == 0 {
                        ready.push(ch.clone());
                        ready.sort();
                    }
                }
            }
        }
    }
    if ordered.len() != chain_set.len() {
        return Err(MonteCarloExecError::Domain(String::from("cycle detected in Monte Carlo downstream analysis chain")));
    }
    Ok(ordered)
}

fn assemble_scratch_doc(
    doc: &ProjectDocument,
    source_id: &SheetId,
    chain_set: &HashSet<SheetId>,
    ordered: &[SheetId],
) -> Result<ProjectDocument, MonteCarloExecError> {
    let mut scratch = ProjectDocument::new("mc-scratch").map_err(|e| MonteCarloExecError::Domain(e.to_string()))?;
    scratch.info_sheets.clone_from(&doc.info_sheets);

    let mut needed_data: HashSet<SheetId> = HashSet::new();
    let mut needed_static_results: HashSet<SheetId> = HashSet::new();
    if doc.data_sheet(source_id).is_some() {
        needed_data.insert(source_id.clone());
    } else if doc.result_sheet(source_id).is_some() {
        needed_static_results.insert(source_id.clone());
    }
    for cid in ordered {
        if let Some(rs) = doc.result_sheet(cid) {
            for up in rs.analysis.source_sheet_id.iter().cloned().chain(rs.analysis.kind.upstream_sheet_ids()) {
                if !chain_set.contains(&up) {
                    if doc.data_sheet(&up).is_some() {
                        needed_data.insert(up);
                    } else if doc.result_sheet(&up).is_some() {
                        needed_static_results.insert(up);
                    }
                }
            }
        }
    }

    for ds_id in needed_data {
        if let Some(ds) = doc.data_sheet(&ds_id) {
            scratch.data_sheets.push(ds.clone());
        }
    }
    for rs_id in needed_static_results {
        if let Some(rs) = doc.result_sheet(&rs_id) {
            scratch.result_sheets.push(rs.clone());
        }
    }
    for cid in ordered {
        if let Some(rs) = doc.result_sheet(cid) {
            scratch.result_sheets.push(rs.clone());
        }
    }
    Ok(scratch)
}

fn inject_simulated_source(scratch: &mut ProjectDocument, source_id: &SheetId, sim_ds: DataSheet) {
    if let Some(ds) = scratch.data_sheet_mut(source_id) {
        *ds = sim_ds;
        return;
    }
    if let Some(rs) = scratch.result_sheet_mut(source_id) {
        rs.analyzable_data = Some(sim_ds);
        rs.status = ResultStatus::UpToDate;
    }
}

fn resolve_tracked_scalars(
    doc: &ProjectDocument,
    mc: &MonteCarloSpec,
    chain_ids: &[SheetId],
) -> Result<Vec<ResolvedTrackedScalar>, MonteCarloExecError> {
    if !mc.tracked_scalars.is_empty() {
        let mut out = Vec::with_capacity(mc.tracked_scalars.len());
        for ts in &mc.tracked_scalars {
            let target = ts.result_sheet_id.clone().or_else(|| mc.downstream_result_sheet_id.clone());
            out.push(ResolvedTrackedScalar {
                label: ts.label.clone(),
                target_sheet_id: target,
                parameter_key: ts.parameter_key.clone(),
                data_set_index: ts.data_set_index,
                builtin_fallback: None,
            });
        }
        return Ok(out);
    }

    // Downstream sheet supplied without explicit `tracked_scalars`: inspect the downstream sheet's
    // existing finite scalars (up to 8 deduplicated entries) before falling back to simulated-table summaries.
    if !chain_ids.is_empty()
        && let Some(ref ds_id) = mc.downstream_result_sheet_id
        && let Some(ds_rs) = doc.result_sheet(ds_id)
    {
        let mut seen: HashSet<(String, Option<usize>)> = HashSet::new();
        let mut key_counts: HashMap<String, usize> = HashMap::new();
        let mut picked: Vec<(String, Option<usize>)> = Vec::new();
        for entry in &ds_rs.scalars {
            if !entry.value.is_finite() {
                continue;
            }
            let norm_key = entry.key.to_ascii_lowercase();
            if seen.insert((norm_key.clone(), entry.data_set_index)) {
                *key_counts.entry(norm_key).or_insert(0) += 1;
                picked.push((entry.key.clone(), entry.data_set_index));
                if picked.len() >= 8 {
                    break;
                }
            }
        }
        if !picked.is_empty() {
            let out = picked
                .into_iter()
                .map(|(key, data_set_index)| {
                    let dup_key = key_counts.get(&key.to_ascii_lowercase()).copied().unwrap_or(0) > 1;
                    let label = match data_set_index {
                        Some(idx) if dup_key => format!("{key} [{idx}]"),
                        _ => key.clone(),
                    };
                    ResolvedTrackedScalar { label, target_sheet_id: Some(ds_id.clone()), parameter_key: key, data_set_index, builtin_fallback: None }
                })
                .collect();
            return Ok(out);
        }
    }

    Ok(vec![
        ResolvedTrackedScalar {
            label: String::from("Simulated Mean"),
            target_sheet_id: None,
            parameter_key: String::from("Simulated Mean"),
            data_set_index: None,
            builtin_fallback: Some(BuiltinSimSummary::Mean),
        },
        ResolvedTrackedScalar {
            label: String::from("Simulated SD"),
            target_sheet_id: None,
            parameter_key: String::from("Simulated SD"),
            data_set_index: None,
            builtin_fallback: Some(BuiltinSimSummary::Sd),
        },
        ResolvedTrackedScalar {
            label: String::from("Simulated Median"),
            target_sheet_id: None,
            parameter_key: String::from("Simulated Median"),
            data_set_index: None,
            builtin_fallback: Some(BuiltinSimSummary::Median),
        },
    ])
}

fn is_fit_flagged_or_unconverged(rs: &ResultSheet) -> bool {
    if !matches!(rs.analysis.kind, AnalysisKind::NonlinearRegression(_)) {
        return false;
    }
    if rs.fitted_curves.iter().any(|fc| !fc.converged || fc.ambiguous) {
        return true;
    }
    // Check authoritative `"Fit quality flag"` row emitted by `curvebook_fit::result::append_nonlinear_gof_tab`.
    for tab in &rs.tabs {
        if tab.id == "nonlinear_gof" {
            for (r_idx, label) in tab.row_labels.iter().enumerate() {
                if label == "Fit quality flag"
                    && let Some(row) = tab.rows.get(r_idx)
                    && row.iter().any(|cell| matches!(cell, ResultCell::Text(s) if s.eq_ignore_ascii_case("flagged")))
                {
                    return true;
                }
            }
        }
    }
    for item in &rs.checklist {
        let lc = item.assumption.to_ascii_lowercase();
        if item.status == ChecklistStatus::Violated && (lc.contains("ambiguous") || lc.contains("fit quality") || lc.contains("convergence")) {
            return true;
        }
        if item.status == ChecklistStatus::Warn && lc.contains("fit quality") {
            return true;
        }
    }
    false
}

fn extract_tracked_values(scratch: &ProjectDocument, sim_ds: &DataSheet, tracked: &[ResolvedTrackedScalar]) -> Vec<Option<f64>> {
    let mut sim_vals_cache: Option<Vec<f64>> = None;
    let mut out = Vec::with_capacity(tracked.len());
    for ts in tracked {
        if let Some(kind) = ts.builtin_fallback {
            let vals = sim_vals_cache.get_or_insert_with(|| collect_active_finite_numbers(sim_ds));
            out.push(compute_builtin_summary(vals, kind));
            continue;
        }
        let val = ts.target_sheet_id.as_ref().and_then(|sid| scratch.result_sheet(sid)).and_then(|rs| {
            rs.lookup_scalar(&ts.parameter_key, ts.data_set_index).or_else(|| {
                if ts.data_set_index.is_none() {
                    rs.scalars
                        .iter()
                        .find(|s| s.key == ts.parameter_key)
                        .or_else(|| rs.scalars.iter().find(|s| s.key.eq_ignore_ascii_case(&ts.parameter_key)))
                        .map(|s| s.value)
                } else {
                    rs.scalars
                        .iter()
                        .find(|s| s.data_set_index == ts.data_set_index && s.key.eq_ignore_ascii_case(&ts.parameter_key))
                        .map(|s| s.value)
                }
            })
        });
        out.push(val.filter(|v| v.is_finite()));
    }
    out
}

fn collect_active_finite_numbers(ds: &DataSheet) -> Vec<f64> {
    let mut out = Vec::new();
    match &ds.archetype {
        TableArchetype::Xy(t) => collect_columns_numbers(&t.data_sets, &mut out),
        TableArchetype::Column(t) => collect_columns_numbers(&t.data_sets, &mut out),
        TableArchetype::Grouped(t) => collect_columns_numbers(&t.data_sets, &mut out),
        TableArchetype::Contingency(t) => collect_columns_numbers(&t.data_sets, &mut out),
        TableArchetype::PartsOfWhole(t) => collect_columns_numbers(&t.data_sets, &mut out),
        TableArchetype::Survival(t) => {
            for c in &t.times {
                if let Some(v) = c.active_number() {
                    out.push(v);
                }
            }
        }
        TableArchetype::MultipleVariables(t) => {
            for v in &t.variables {
                for c in &v.cells {
                    if let Some(num) = c.active_number() {
                        out.push(num);
                    }
                }
            }
        }
        TableArchetype::Nested(t) => {
            for g in &t.groups {
                for row in &g.cells {
                    for c in row {
                        if let Some(num) = c.active_number() {
                            out.push(num);
                        }
                    }
                }
            }
        }
    }
    out
}

fn collect_columns_numbers(cols: &[DataSetColumn], out: &mut Vec<f64>) {
    for col in cols {
        for row in &col.cells {
            for c in row {
                if let Some(v) = c.active_number() {
                    out.push(v);
                }
            }
        }
    }
}

fn compute_builtin_summary(vals: &[f64], kind: BuiltinSimSummary) -> Option<f64> {
    if vals.is_empty() {
        return None;
    }
    let stats = summarize_distribution(vals)?;
    match kind {
        BuiltinSimSummary::Mean => Some(stats.mean),
        BuiltinSimSummary::Sd => stats.sd.or(Some(0.0)),
        BuiltinSimSummary::Median => Some(stats.median),
    }
}

fn evaluate_hit_rules(rules: &[MonteCarloHitRule], values: &[f64]) -> bool {
    for rule in rules {
        let Some(&val) = values.get(rule.scalar_index) else {
            return false;
        };
        if !val.is_finite() {
            return false;
        }
        let passed = match rule.op {
            MonteCarloHitOp::LessThan => val < rule.threshold,
            MonteCarloHitOp::LessOrEqual => val <= rule.threshold,
            MonteCarloHitOp::GreaterThan => val > rule.threshold,
            MonteCarloHitOp::GreaterOrEqual => val >= rule.threshold,
            MonteCarloHitOp::Between => rule.upper_threshold.is_some_and(|hi| val >= rule.threshold && val <= hi),
        };
        if !passed {
            return false;
        }
    }
    true
}

struct DistSummary {
    n: usize,
    mean: f64,
    sd: Option<f64>,
    sem: Option<f64>,
    median: f64,
    q1: f64,
    q3: f64,
    iqr: f64,
    min: f64,
    max: f64,
    p025: f64,
    p975: f64,
}

#[allow(clippy::cast_precision_loss)]
fn summarize_distribution(values: &[f64]) -> Option<DistSummary> {
    if values.is_empty() {
        return None;
    }
    let mut sorted: Vec<f64> = values.iter().copied().filter(|v| v.is_finite()).collect();
    if sorted.is_empty() {
        return None;
    }
    sorted.sort_by(f64::total_cmp);
    let n = sorted.len();
    let mut mean = 0.0_f64;
    let mut m2 = 0.0_f64;
    for (idx, &x) in sorted.iter().enumerate() {
        let k = (idx + 1) as f64;
        let delta = x - mean;
        mean += delta / k;
        let delta2 = x - mean;
        m2 += delta * delta2;
    }
    let sd = if n >= 2 { Some((m2 / ((n - 1) as f64)).max(0.0).sqrt()) } else { None };
    let sem = sd.map(|s| s / (n as f64).sqrt());
    let min = *sorted.first()?;
    let max = *sorted.last()?;
    let median = quantile_type6_sorted(&sorted, 0.5).unwrap_or(min);
    let q1 = quantile_type6_sorted(&sorted, 0.25).unwrap_or(min);
    let q3 = quantile_type6_sorted(&sorted, 0.75).unwrap_or(max);
    let p025 = quantile_type6_sorted(&sorted, 0.025).unwrap_or(min);
    let p975 = quantile_type6_sorted(&sorted, 0.975).unwrap_or(max);
    Some(DistSummary { n, mean, sd, sem, median, q1, q3, iqr: q3 - q1, min, max, p025, p975 })
}

#[allow(clippy::too_many_arguments, clippy::cast_precision_loss)]
fn build_monte_carlo_result_sheet(
    existing: &ResultSheet,
    mc: &MonteCarloSpec,
    tracked: &[ResolvedTrackedScalar],
    exclude_flagged: bool,
    counts: &MonteCarloCounts,
    all_samples: &[Vec<f64>],
    hit_samples: &[Vec<f64>],
    not_hit_samples: &[Vec<f64>],
    preview_all: &[PreviewRow],
    preview_hits: &[PreviewRow],
    preview_not_hits: &[PreviewRow],
    analyzable_rows: &[(usize, bool, Vec<f64>)],
) -> Result<ResultSheet, MonteCarloExecError> {
    let mut result = ResultSheet::new(existing.analysis.clone()).map_err(|e| MonteCarloExecError::Domain(e.to_string()))?;

    let hit_rate = if counts.retained > 0 { (counts.hits as f64) / (counts.retained as f64) } else { 0.0 };
    let hit_rate_pct = hit_rate * 100.0;
    let alpha = existing.analysis.confidence_level.alpha();
    let hit_ci = if counts.retained > 0 { wilson_score_ci(counts.hits as f64, counts.retained as f64, alpha) } else { None };

    // 1. Overview tab.
    let mut overview_footnotes =
        vec![format!("Deterministic SplitMix64/Xoshiro256** per-iteration seed schedule anchored at master seed {}.", mc.seed)];
    if mc.hit_rules.is_empty() {
        overview_footnotes.push(String::from("No hit rules configured; all retained iterations satisfy the empty predicate conjunction."));
    }
    if exclude_flagged {
        overview_footnotes
            .push(String::from("Flagged, ambiguous, and non-converged nonlinear fits were excluded from All, Hits, and Not Hits summaries."));
    }
    let ci_cell = match hit_ci {
        Some((lo, hi)) if lo.is_finite() && hi.is_finite() => {
            ResultCell::ConfidenceInterval { lower: CiBound::Finite(lo * 100.0), upper: CiBound::Finite(hi * 100.0) }
        }
        _ => ResultCell::Empty,
    };
    let conf_pct_label = format!("{}% CI (Wilson) for Hit rate (%)", existing.analysis.confidence_level.percent());
    result.tabs.push(ResultTab {
        id: String::from("mc-overview"),
        title: String::from("Monte Carlo simulation overview"),
        kind: ResultTabKind::MainSummary,
        column_headers: vec![String::from("Value")],
        row_labels: vec![
            String::from("Master seed"),
            String::from("Iterations requested"),
            String::from("Iterations simulated"),
            String::from("Retained iterations (All)"),
            String::from("Excluded iterations (Flagged/Ambiguous/Unconverged)"),
            String::from("Failed iterations"),
            String::from("Missing-scalar iterations"),
            String::from("Hits"),
            String::from("Not Hits"),
            String::from("Hit rate (proportion)"),
            String::from("Hit rate (%)"),
            conf_pct_label,
        ],
        rows: vec![
            vec![num_cell(mc.seed as f64)],
            vec![num_cell(counts.requested as f64)],
            vec![num_cell(counts.completed as f64)],
            vec![num_cell(counts.retained as f64)],
            vec![num_cell(counts.excluded_flagged as f64)],
            vec![num_cell(counts.failed as f64)],
            vec![num_cell(counts.missing_scalar as f64)],
            vec![num_cell(counts.hits as f64)],
            vec![num_cell(counts.not_hits as f64)],
            vec![num_cell(hit_rate)],
            vec![num_cell(hit_rate_pct)],
            vec![ci_cell],
        ],
        footnotes: overview_footnotes,
    });

    // 2. Summary tabs: All, Hits, Not Hits.
    result.tabs.push(build_summary_tab("mc-summary-all", "All — Summary", tracked, all_samples));
    result.tabs.push(build_summary_tab("mc-summary-hits", "Hits — Summary", tracked, hit_samples));
    result.tabs.push(build_summary_tab("mc-summary-not-hits", "Not Hits — Summary", tracked, not_hit_samples));

    // 3. Per-iteration diagnostic tabs: All, Hits, Not Hits.
    result.tabs.push(build_iterations_tab("mc-iterations-all", "All — Iterations", tracked, preview_all, counts.requested));
    result.tabs.push(build_iterations_tab("mc-iterations-hits", "Hits — Iterations", tracked, preview_hits, counts.hits));
    result.tabs.push(build_iterations_tab("mc-iterations-not-hits", "Not Hits — Iterations", tracked, preview_not_hits, counts.not_hits));

    // 4. Hookable scalars.
    result.scalars.extend([
        scalar_entry("Iterations", counts.requested as f64, None),
        scalar_entry("RetainedIterations", counts.retained as f64, None),
        scalar_entry("ExcludedIterations", counts.excluded_flagged as f64, None),
        scalar_entry("FailedIterations", counts.failed as f64, None),
        scalar_entry("Hits", counts.hits as f64, None),
        scalar_entry("NotHits", counts.not_hits as f64, None),
        scalar_entry("HitRate", hit_rate, None),
        scalar_entry("HitRatePercent", hit_rate_pct, Some("%")),
    ]);
    for (idx, ts) in tracked.iter().enumerate() {
        if let Some(samples) = all_samples.get(idx)
            && let Some(s) = summarize_distribution(samples)
        {
            result.scalars.push(scalar_entry(&format!("{} (All Mean)", ts.label), s.mean, None));
            if let Some(sd) = s.sd {
                result.scalars.push(scalar_entry(&format!("{} (All SD)", ts.label), sd, None));
            }
            result.scalars.push(scalar_entry(&format!("{} (All Median)", ts.label), s.median, None));
        }
        if let Some(samples) = hit_samples.get(idx)
            && let Some(s) = summarize_distribution(samples)
        {
            result.scalars.push(scalar_entry(&format!("{} (Hits Mean)", ts.label), s.mean, None));
        }
        if let Some(samples) = not_hit_samples.get(idx)
            && let Some(s) = summarize_distribution(samples)
        {
            result.scalars.push(scalar_entry(&format!("{} (Not Hits Mean)", ts.label), s.mean, None));
        }
    }

    // 5. Checklist items.
    result.checklist.push(ChecklistItem {
        assumption: String::from("Deterministic Monte Carlo seed"),
        status: ChecklistStatus::Info,
        diagnostic_metric: Some(format!("seed = {}, iterations = {}", mc.seed, mc.iterations)),
        explanation: String::from("Per-iteration seeds are deterministically derived from the master seed for reproducible simulations."),
        remediation: None,
    });
    if exclude_flagged {
        let exclusion_note = if counts.excluded_flagged > 0 {
            format!(
                "{} iteration(s) with flagged, ambiguous, or non-converged nonlinear fits were excluded from Monte Carlo summary statistics. Inspect `All — Iterations` and tighten parameter bounds or initial guesses if the exclusion rate is high.",
                counts.excluded_flagged
            )
        } else {
            String::from("0 iterations had flagged, ambiguous, or non-converged nonlinear fits.")
        };
        result.checklist.push(ChecklistItem {
            assumption: String::from("Flagged-fit exclusion policy"),
            status: if counts.excluded_flagged == 0 { ChecklistStatus::Pass } else { ChecklistStatus::Warn },
            diagnostic_metric: Some(format!("excluded = {} / {}", counts.excluded_flagged, counts.requested)),
            explanation: exclusion_note,
            remediation: None,
        });
    }
    if counts.failed > 0 || counts.missing_scalar > 0 {
        result.checklist.push(ChecklistItem {
            assumption: String::from("Iteration completion rate"),
            status: ChecklistStatus::Warn,
            diagnostic_metric: Some(format!("failed = {}, missing_scalar = {}", counts.failed, counts.missing_scalar)),
            explanation: format!(
                "{} iteration(s) failed downstream execution and {} lacked a finite tracked scalar. Verify tracked scalar keys and simulation parameter ranges.",
                counts.failed, counts.missing_scalar
            ),
            remediation: None,
        });
    }

    // 6. Analyzable MultipleVariables table for downstream plotting/descriptive stats.
    if let Some(ad) = build_analyzable_mc_table(existing, tracked, analyzable_rows) {
        result.analyzable_data = Some(ad);
    }

    result.status = ResultStatus::UpToDate;
    Ok(result)
}

fn build_summary_tab(id: &str, title: &str, tracked: &[ResolvedTrackedScalar], samples: &[Vec<f64>]) -> ResultTab {
    let headers = vec![
        String::from("N"),
        String::from("Mean"),
        String::from("SD"),
        String::from("SEM"),
        String::from("Median"),
        String::from("Q1"),
        String::from("Q3"),
        String::from("IQR"),
        String::from("Min"),
        String::from("Max"),
        String::from("2.5%"),
        String::from("97.5%"),
    ];
    let mut row_labels = Vec::with_capacity(tracked.len());
    let mut rows = Vec::with_capacity(tracked.len());
    for (idx, ts) in tracked.iter().enumerate() {
        row_labels.push(ts.label.clone());
        let row = match samples.get(idx).and_then(|vals| summarize_distribution(vals)) {
            #[allow(clippy::cast_precision_loss)]
            Some(s) => vec![
                num_cell(s.n as f64),
                num_cell(s.mean),
                opt_num_cell(s.sd),
                opt_num_cell(s.sem),
                num_cell(s.median),
                num_cell(s.q1),
                num_cell(s.q3),
                num_cell(s.iqr),
                num_cell(s.min),
                num_cell(s.max),
                num_cell(s.p025),
                num_cell(s.p975),
            ],
            None => vec![
                num_cell(0.0),
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
                ResultCell::Empty,
            ],
        };
        rows.push(row);
    }
    ResultTab {
        id: id.to_owned(),
        title: title.to_owned(),
        kind: ResultTabKind::MainSummary,
        column_headers: headers,
        row_labels,
        rows,
        footnotes: Vec::new(),
    }
}

fn build_iterations_tab(id: &str, title: &str, tracked: &[ResolvedTrackedScalar], preview: &[PreviewRow], total_in_partition: usize) -> ResultTab {
    let mut headers = Vec::with_capacity(tracked.len() + 3);
    headers.push(String::from("Iteration"));
    headers.push(String::from("Status"));
    headers.push(String::from("Hit"));
    for ts in tracked {
        headers.push(ts.label.clone());
    }
    let mut row_labels = Vec::with_capacity(preview.len());
    let mut rows = Vec::with_capacity(preview.len());
    for item in preview {
        row_labels.push(format!("Iter {}", item.iteration_1based));
        let mut row = Vec::with_capacity(headers.len());
        #[allow(clippy::cast_precision_loss)]
        row.push(num_cell(item.iteration_1based as f64));
        row.push(ResultCell::Text(item.status.to_owned()));
        row.push(match item.hit {
            Some(b) => ResultCell::Boolean(b),
            None => ResultCell::Empty,
        });
        for v in &item.values {
            row.push(opt_num_cell(*v));
        }
        rows.push(row);
    }
    let mut footnotes = Vec::new();
    if total_in_partition > preview.len() {
        footnotes.push(format!(
            "Showing first {} of {} iteration(s) in this partition (full sample summary is computed over all retained iterations).",
            preview.len(),
            total_in_partition
        ));
    }
    ResultTab { id: id.to_owned(), title: title.to_owned(), kind: ResultTabKind::Diagnostics, column_headers: headers, row_labels, rows, footnotes }
}

#[allow(clippy::cast_precision_loss)]
fn build_analyzable_mc_table(existing: &ResultSheet, tracked: &[ResolvedTrackedScalar], rows: &[(usize, bool, Vec<f64>)]) -> Option<DataSheet> {
    if rows.is_empty() {
        return None;
    }
    let n = rows.len();
    let mut variables = Vec::with_capacity(tracked.len() + 2);

    let mut iter_col = VariableColumn::new("Iteration", n).ok()?;
    iter_col.lock_role(VariableRole::Continuous);
    let mut hit_col = VariableColumn::new("Hit", n).ok()?;
    hit_col.lock_role(VariableRole::Categorical);

    let mut scalar_cols = Vec::with_capacity(tracked.len());
    for ts in tracked {
        let mut col = VariableColumn::new(ts.label.clone(), n).ok()?;
        col.lock_role(VariableRole::Continuous);
        scalar_cols.push(col);
    }

    for (r_idx, (iter_1based, is_hit, vals)) in rows.iter().enumerate() {
        if let Some(cell) = iter_col.cells.get_mut(r_idx) {
            *cell = Cell::number(*iter_1based as f64);
        }
        if let Some(cell) = hit_col.cells.get_mut(r_idx) {
            *cell = Cell::text(if *is_hit { "Hit" } else { "Not Hit" });
        }
        for (s_idx, &v) in vals.iter().enumerate() {
            if let Some(cell) = scalar_cols.get_mut(s_idx).and_then(|c| c.cells.get_mut(r_idx)) {
                *cell = Cell::number(v);
            }
        }
    }

    variables.push(iter_col);
    variables.push(hit_col);
    variables.extend(scalar_cols);

    let mv = MultipleVariablesTable { row_titles: vec![String::new(); n], row_titles_expanded: false, variables };
    let out_id = format!("{}_mc_samples", existing.id.as_str());
    let out_title = format!("{} — Samples", existing.title());
    DataSheet::new(out_id, out_title, TableArchetype::MultipleVariables(mv)).ok()
}

const fn num_cell(value: f64) -> ResultCell {
    ResultCell::Number { value, prefix: None, units: None }
}

fn opt_num_cell(value: Option<f64>) -> ResultCell {
    match value.filter(|v| v.is_finite()) {
        Some(v) => num_cell(v),
        None => ResultCell::Empty,
    }
}

fn scalar_entry(key: &str, value: f64, units: Option<&str>) -> ResultScalarEntry {
    ResultScalarEntry { key: key.to_owned(), data_set_index: None, value, units: units.map(str::to_owned) }
}
